import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import ThoughtSpotShell from './components/ThoughtSpotShell';
import { TierProvider } from './config/TierContext';
import Sidebar, { SIDEBAR_WIDTH } from './components/NavHeader';
import TopHeader from './components/TopHeader';
import DashboardHome from './pages/DashboardHome';
import SearchPage from './pages/SearchPage';
import Portfolios from './pages/Portfolios';
import PlaceholderPage from './pages/PlaceholderPage';
import Analytics from './pages/Analytics';
import './App.css';

function App() {
  return (
    <TierProvider>
      <ThoughtSpotShell>
        <Router>
          <div className="App" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#F9FAFB' }}>
            <Sidebar />
            <div
              style={{
                marginLeft: SIDEBAR_WIDTH,
                flex: 1,
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
              }}
            >
              <TopHeader />
              <main style={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
                <Routes>
                  <Route path="/" element={<Navigate to="/dashboard" replace />} />
                  <Route path="/dashboard" element={<DashboardHome />} />
                  <Route path="/search" element={<SearchPage />} />
                  <Route path="/portfolios" element={<Portfolios />} />
                  <Route
                    path="/idv-aml"
                    element={
                      <PlaceholderPage
                        title="IDV & AML"
                        description="Identity verification and anti-money-laundering workflows can be wired here."
                      />
                    }
                  />
                  <Route
                    path="/international-checks"
                    element={
                      <PlaceholderPage
                        title="International Checks"
                        description="Connect international screening and checks when ready."
                      />
                    }
                  />
                  <Route path="/analytics" element={<Analytics />} />
                  <Route
                    path="/advanced-investigations"
                    element={<PlaceholderPage title="Advanced Investigations" />}
                  />
                  <Route
                    path="/consumer-credit"
                    element={<PlaceholderPage title="Consumer Credit Report" />}
                  />
                  <Route path="/knowledge-hub" element={<PlaceholderPage title="Knowledge Hub" />} />
                </Routes>
              </main>
            </div>
          </div>
        </Router>
      </ThoughtSpotShell>
    </TierProvider>
  );
}

export default App;
